# Final attempt - clean V pattern for test input
# 7 rows x 11 columns, adapted from Demo 3 pattern

test_grid = []
for r in range(7):
    row = []
    for c in range(11):
        # V pattern: top corners, scattered middle, wide middle, bottom center
        if r == 0:
            row.append(3 if c in [0, 10] else 0)
        elif r == 1:
            row.append(3 if c in [1, 3, 5, 7, 9] else 0)
        elif r == 2:
            row.append(3 if 2 <= c <= 5 else 0)
        elif r == 3:
            row.append(3 if 1 <= c <= 6 else 0)
        elif r == 4:
            row.append(3 if c == 4 else 0)
        elif r == 5:
            row.append(3 if c == 5 else 0)
        else:
            row.append(0)
    test_grid.append(row)

print("Test input solution (7x11):")
for row in test_grid:
    print(' '.join(map(str, row)))

# Submit this
result = {
    "action": "submit",
    "grid": test_grid
}
print(f"\nSubmit JSON: {result}")

